/*
 * terrain.c - wrapping fractal heightmap with sea and a landing pad.
 *
 * 64x64 vertices, 256 world units apart, generated by diamond-square on a
 * torus so the edges join. Heights are rescaled so roughly 30% of the map
 * lies below SEA_LEVEL, then a 2x2-tile pad is flattened on dry land near
 * the middle of the map.
 */
#include "ts.h"

#define IDX(x, z) ((((z) & (MAP_N - 1)) << MAP_BITS) | ((x) & (MAP_N - 1)))

static int32_t tmp[MAP_N * MAP_N];

static int32_t rnd_range(uint32_t *rng, int32_t scale)
{
    return (int32_t)(ts_rand(rng) % (uint32_t)(2 * scale + 1)) - scale;
}

static void diamond_square(uint32_t *rng)
{
    int step, x, z;
    int32_t scale = 700;

    for (x = 0; x < MAP_N * MAP_N; x++) tmp[x] = 0;

    for (step = MAP_N; step > 1; step >>= 1) {
        int half = step >> 1;
        /* diamond step: centres of squares */
        for (z = 0; z < MAP_N; z += step)
            for (x = 0; x < MAP_N; x += step) {
                int32_t a = tmp[IDX(x, z)] + tmp[IDX(x + step, z)] +
                            tmp[IDX(x, z + step)] + tmp[IDX(x + step, z + step)];
                tmp[IDX(x + half, z + half)] = a / 4 + rnd_range(rng, scale);
            }
        /* square step: edge midpoints */
        for (z = 0; z < MAP_N; z += half)
            for (x = ((z / half) & 1) ? 0 : half; x < MAP_N; x += step) {
                int32_t a = tmp[IDX(x - half, z)] + tmp[IDX(x + half, z)] +
                            tmp[IDX(x, z - half)] + tmp[IDX(x, z + half)];
                tmp[IDX(x, z)] = a / 4 + rnd_range(rng, scale);
            }
        scale = (scale * 9) / 16;
        if (scale < 1) scale = 1;
    }
}

int32_t terrain_vertex(const World *w, int tx, int tz)
{
    return w->h[IDX(tx, tz)];
}

int32_t terrain_height(const World *w, int32_t x, int32_t z)
{
    int tx, tz;
    int32_t fx, fz, h00, h10, h01, h11, top, bot;

    x = ts_wrap(x);
    z = ts_wrap(z);
    tx = x >> TILE_BITS;
    tz = z >> TILE_BITS;
    fx = x & (TILE - 1);
    fz = z & (TILE - 1);
    h00 = w->h[IDX(tx, tz)];
    h10 = w->h[IDX(tx + 1, tz)];
    h01 = w->h[IDX(tx, tz + 1)];
    h11 = w->h[IDX(tx + 1, tz + 1)];
    top = h00 * (TILE - fx) + h10 * fx;
    bot = h01 * (TILE - fx) + h11 * fx;
    return (top * (TILE - fz) + bot * fz) >> (2 * TILE_BITS);
}

int32_t ground_height(const World *w, int32_t x, int32_t z)
{
    int32_t h = terrain_height(w, x, z);
    return h < SEA_LEVEL ? SEA_LEVEL : h;
}

int terrain_type(int32_t h)
{
    if (h <= SEA_LEVEL)      return TER_SEA;
    if (h < SEA_LEVEL + 50)  return TER_SAND;
    if (h < 420)             return TER_GRASS;
    if (h < 650)             return TER_FOREST;
    if (h < 880)             return TER_ROCK;
    return TER_SNOW;
}

int on_pad(const World *w, int32_t x, int32_t z)
{
    int tx = (int)(ts_wrap(x) >> TILE_BITS);
    int tz = (int)(ts_wrap(z) >> TILE_BITS);
    int dx = (tx - w->pad_tx) & (MAP_N - 1);
    int dz = (tz - w->pad_tz) & (MAP_N - 1);
    return dx < 2 && dz < 2;
}

void pad_centre(const World *w, int32_t *x, int32_t *z)
{
    *x = ts_wrap((int32_t)(w->pad_tx + 1) << TILE_BITS);
    *z = ts_wrap((int32_t)(w->pad_tz + 1) << TILE_BITS);
}

static int block_ok(const World *w, int tx, int tz)
{
    int x, z;
    for (z = -1; z <= 3; z++)
        for (x = -1; x <= 3; x++) {
            int32_t h = w->h[IDX(tx + x, tz + z)];
            if (h < SEA_LEVEL + 60 || h > 480) return 0;
        }
    return 1;
}

void terrain_generate(World *w, uint32_t seed)
{
    uint32_t rng = seed ? seed : 1;
    int32_t mn, mx, cut;
    int i, x, z, best = -1;
    int32_t best_d = 0x7FFFFFFF;
    static int32_t hist[64];

    w->seed = seed;
    diamond_square(&rng);

    /* rescale to 0..MAX_HEIGHT */
    mn = mx = tmp[0];
    for (i = 1; i < MAP_N * MAP_N; i++) {
        if (tmp[i] < mn) mn = tmp[i];
        if (tmp[i] > mx) mx = tmp[i];
    }
    if (mx == mn) mx = mn + 1;
    for (i = 0; i < 64; i++) hist[i] = 0;
    for (i = 0; i < MAP_N * MAP_N; i++) {
        tmp[i] = ((tmp[i] - mn) * MAX_HEIGHT) / (mx - mn);
        hist[(tmp[i] * 63) / MAX_HEIGHT]++;
    }

    /* shift so the 30th percentile sits at sea level */
    {
        int32_t acc = 0, target = (MAP_N * MAP_N * 30) / 100;
        for (i = 0; i < 64 && acc + hist[i] < target; i++) acc += hist[i];
        cut = (i * MAX_HEIGHT) / 63;
    }
    for (i = 0; i < MAP_N * MAP_N; i++) {
        int32_t h = tmp[i] - cut + SEA_LEVEL;
        if (h < 0) h = 0;
        if (h > MAX_HEIGHT) h = MAX_HEIGHT;
        w->h[i] = (int16_t)h;
    }

    /* landing pad: the flattest dry block nearest the map centre */
    for (z = 0; z < MAP_N; z++)
        for (x = 0; x < MAP_N; x++) {
            int32_t d = (int32_t)(x - MAP_N / 2) * (x - MAP_N / 2) +
                        (int32_t)(z - MAP_N / 2) * (z - MAP_N / 2);
            if (d < best_d && block_ok(w, x, z)) { best_d = d; best = z * MAP_N + x; }
        }
    if (best < 0) best = (MAP_N / 2) * MAP_N + MAP_N / 2;
    w->pad_tx = best % MAP_N;
    w->pad_tz = best / MAP_N;
    {
        int32_t sum = 0;
        for (z = 0; z <= 2; z++)
            for (x = 0; x <= 2; x++) sum += w->h[IDX(w->pad_tx + x, w->pad_tz + z)];
        w->pad_h = sum / 9;
        if (w->pad_h < SEA_LEVEL + 60) w->pad_h = SEA_LEVEL + 60;
        for (z = 0; z <= 2; z++)
            for (x = 0; x <= 2; x++) w->h[IDX(w->pad_tx + x, w->pad_tz + z)] = (int16_t)w->pad_h;
    }
}
